namespace CourseCatalog.Models;

public class Course
{
    public int Id { get; set; }
    public required string Code { get; set; }
    public required string Title { get; set; }
    public required string Description { get; set; }
    public int Credits { get; set; }
    public required string Schedule { get; set; }
    public required string DepartmentCode { get; set; }
    public required string InstructorName { get; set; }
    public required string InstructorBio { get; set; }
    public bool IsFeatured { get; set; }
}

namespace CourseCatalog.Models;

public class Department
{
    public required string Code { get; set; }
    public required string Name { get; set; }
}

using System.ComponentModel.DataAnnotations;

namespace CourseCatalog.Models;

public class EnrollmentRequest
{
    [Required(ErrorMessage = "Full name is required.")]
    [StringLength(100)]
    public string FullName { get; set; } = "";

    [Required(ErrorMessage = "Student ID is required.")]
    [RegularExpression(@"^[A-Z]{2}\d{6}$", ErrorMessage = "Student ID must be 2 letters followed by 6 digits (e.g., CS123456).")]
    public string StudentId { get; set; } = "";

    [Required(ErrorMessage = "Please select a course.")]
    [Range(1, int.MaxValue, ErrorMessage = "Please select a course.")]
    public int CourseId { get; set; }
}

using CourseCatalog.Models;

namespace CourseCatalog.Services;

public interface ICatalogService
{
    Task<IReadOnlyList<Department>> GetDepartmentsAsync();
    Task<IReadOnlyList<Course>> GetCoursesAsync(string? searchTerm = null, string? departmentCode = null);
    Task<IReadOnlyList<Course>> GetFeaturedCoursesAsync();
    Task<Course?> GetCourseByIdAsync(int id);
    Task SubmitEnrollmentAsync(EnrollmentRequest request);
}

using CourseCatalog.Models;

namespace CourseCatalog.Services;

public class InMemoryCatalogService : ICatalogService
{
    private static readonly List<Department> Departments =
    [
        new() { Code = "CS", Name = "Computer Science" },
        new() { Code = "MATH", Name = "Mathematics" },
        new() { Code = "ENG", Name = "English" },
        new() { Code = "PHYS", Name = "Physics" },
        new() { Code = "HIST", Name = "History" },
    ];

    private static readonly List<Course> Courses =
    [
        new()
        {
            Id = 1, Code = "CS 101", Title = "Introduction to Computer Science",
            Description = "A broad introduction to computing concepts including algorithms, data structures, and programming fundamentals using Python.",
            Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", DepartmentCode = "CS",
            InstructorName = "Dr. Ada Lovelace", InstructorBio = "Dr. Lovelace holds a Ph.D. in Computer Science from MIT and has 15 years of teaching experience in introductory programming and algorithms.",
            IsFeatured = true
        },
        new()
        {
            Id = 2, Code = "CS 301", Title = "Data Structures and Algorithms",
            Description = "Study of fundamental data structures (trees, graphs, hash tables) and algorithm design techniques (divide-and-conquer, dynamic programming, greedy algorithms).",
            Credits = 4, Schedule = "Tue/Thu 10:30 AM–12:00 PM", DepartmentCode = "CS",
            InstructorName = "Dr. Alan Turing", InstructorBio = "Dr. Turing is a renowned researcher in computational theory with over 50 published papers on algorithm optimization.",
            IsFeatured = false
        },
        new()
        {
            Id = 3, Code = "CS 410", Title = "Machine Learning",
            Description = "Introduction to machine learning techniques including supervised and unsupervised learning, neural networks, and practical applications using modern frameworks.",
            Credits = 3, Schedule = "Mon/Wed 2:00–3:30 PM", DepartmentCode = "CS",
            InstructorName = "Dr. Grace Hopper", InstructorBio = "Dr. Hopper specializes in AI and machine learning, having worked at leading tech companies before joining academia.",
            IsFeatured = true
        },
        new()
        {
            Id = 4, Code = "MATH 201", Title = "Linear Algebra",
            Description = "Vectors, matrices, linear transformations, eigenvalues, and applications to computer graphics and data science.",
            Credits = 3, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", DepartmentCode = "MATH",
            InstructorName = "Dr. Emmy Noether", InstructorBio = "Dr. Noether is an award-winning mathematician whose research focuses on abstract algebra and theoretical physics applications.",
            IsFeatured = true
        },
        new()
        {
            Id = 5, Code = "MATH 301", Title = "Differential Equations",
            Description = "Ordinary differential equations, Laplace transforms, series solutions, and applications in engineering and physics.",
            Credits = 4, Schedule = "Tue/Thu 1:00–2:30 PM", DepartmentCode = "MATH",
            InstructorName = "Dr. Bernhard Riemann", InstructorBio = "Dr. Riemann brings 20 years of experience in applied mathematics and differential geometry.",
            IsFeatured = false
        },
        new()
        {
            Id = 6, Code = "ENG 101", Title = "Composition and Rhetoric",
            Description = "Fundamentals of academic writing, argumentation, and critical reading. Students complete multiple essay drafts with peer review.",
            Credits = 3, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", DepartmentCode = "ENG",
            InstructorName = "Prof. Maya Angelou", InstructorBio = "Prof. Angelou is a published author and writing instructor with expertise in creative nonfiction and rhetorical analysis.",
            IsFeatured = false
        },
        new()
        {
            Id = 7, Code = "ENG 250", Title = "World Literature",
            Description = "Survey of major literary works from diverse global traditions, exploring themes of identity, power, and cultural exchange.",
            Credits = 3, Schedule = "Tue/Thu 3:00–4:30 PM", DepartmentCode = "ENG",
            InstructorName = "Dr. Chinua Achebe", InstructorBio = "Dr. Achebe is a literary scholar specializing in postcolonial literature and comparative cultural studies.",
            IsFeatured = true
        },
        new()
        {
            Id = 8, Code = "PHYS 201", Title = "Classical Mechanics",
            Description = "Newtonian mechanics, conservation laws, oscillations, rotational dynamics, and an introduction to Lagrangian mechanics.",
            Credits = 4, Schedule = "Mon/Wed/Fri 1:00–1:50 PM", DepartmentCode = "PHYS",
            InstructorName = "Dr. Richard Feynman", InstructorBio = "Dr. Feynman is celebrated for making complex physics concepts accessible. He has received multiple teaching excellence awards.",
            IsFeatured = false
        },
        new()
        {
            Id = 9, Code = "PHYS 310", Title = "Quantum Physics",
            Description = "Wave-particle duality, Schrödinger equation, quantum states, measurement theory, and applications in modern technology.",
            Credits = 3, Schedule = "Tue/Thu 9:00–10:30 AM", DepartmentCode = "PHYS",
            InstructorName = "Dr. Niels Bohr", InstructorBio = "Dr. Bohr is a leading quantum physicist whose lab has contributed groundbreaking research in quantum computing.",
            IsFeatured = true
        },
        new()
        {
            Id = 10, Code = "HIST 101", Title = "World History to 1500",
            Description = "Survey of global civilizations from antiquity through the late medieval period, covering political, social, and cultural developments.",
            Credits = 3, Schedule = "Tue/Thu 11:00 AM–12:30 PM", DepartmentCode = "HIST",
            InstructorName = "Dr. Howard Zinn", InstructorBio = "Dr. Zinn is a historian focused on social movements and underrepresented perspectives in historical narratives.",
            IsFeatured = false
        },
    ];

    public Task<IReadOnlyList<Department>> GetDepartmentsAsync()
        => Task.FromResult<IReadOnlyList<Department>>(Departments);

    public Task<IReadOnlyList<Course>> GetCoursesAsync(string? searchTerm = null, string? departmentCode = null)
    {
        IEnumerable<Course> results = Courses;

        if (!string.IsNullOrWhiteSpace(departmentCode))
            results = results.Where(c => c.DepartmentCode == departmentCode);

        if (!string.IsNullOrWhiteSpace(searchTerm))
            results = results.Where(c =>
                c.Title.Contains(searchTerm, StringComparison.OrdinalIgnoreCase) ||
                c.Code.Contains(searchTerm, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(searchTerm, StringComparison.OrdinalIgnoreCase));

        return Task.FromResult<IReadOnlyList<Course>>(results.ToList());
    }

    public Task<IReadOnlyList<Course>> GetFeaturedCoursesAsync()
        => Task.FromResult<IReadOnlyList<Course>>(Courses.Where(c => c.IsFeatured).ToList());

    public Task<Course?> GetCourseByIdAsync(int id)
        => Task.FromResult(Courses.FirstOrDefault(c => c.Id == id));

    public Task SubmitEnrollmentAsync(EnrollmentRequest request)
        => Task.CompletedTask; // In production, persist to a database
}

