@using CourseCatalog.Models

<div class="card h-100 shadow-sm">
    <div class="card-body">
        <span class="badge bg-secondary mb-2">@Course.Code</span>
        <h5 class="card-title">@Course.Title</h5>
        <p class="card-text text-muted">@Course.Description[..Math.Min(Course.Description.Length, 120)]@(Course.Description.Length > 120 ? "…" : "")</p>
        <div class="d-flex justify-content-between align-items-center">
            <small class="text-muted">@Course.Credits credits · @Course.DepartmentCode</small>
            <a href="@($"course/{Course.Id}")" class="btn btn-sm btn-outline-primary">Details</a>
        </div>
    </div>
</div>

@code {
    [Parameter, EditorRequired]
    public required Course Course { get; set; }
}

@using CourseCatalog.Models

<div class="card mt-4">
    <div class="card-body">
        <h5 class="card-title">About the Instructor</h5>
        <h6 class="card-subtitle mb-2 text-muted">@Name</h6>
        <p class="card-text">@Bio</p>
    </div>
</div>

@code {
    [Parameter, EditorRequired]
    public required string Name { get; set; }

    [Parameter, EditorRequired]
    public required string Bio { get; set; }
}

@using CourseCatalog.Models

<div class="row mb-4">
    <div class="col-md-6">
        <input type="text" class="form-control" placeholder="Search courses…"
               @bind="SearchTerm" @bind:event="oninput" @bind:after="OnFilterChanged" />
    </div>
    <div class="col-md-4">
        <select class="form-select" @bind="SelectedDepartment" @bind:after="OnFilterChanged">
            <option value="">All Departments</option>
            @foreach (var dept in Departments)
            {
                <option value="@dept.Code">@dept.Name</option>
            }
        </select>
    </div>
</div>

@code {
    [Parameter] public IReadOnlyList<Department> Departments { get; set; } = [];
    [Parameter] public EventCallback<(string? Search, string? Department)> FiltersChanged { get; set; }

    private string SearchTerm { get; set; } = "";
    private string SelectedDepartment { get; set; } = "";

    private async Task OnFilterChanged()
    {
        await FiltersChanged.InvokeAsync((
            string.IsNullOrWhiteSpace(SearchTerm) ? null : SearchTerm,
            string.IsNullOrWhiteSpace(SelectedDepartment) ? null : SelectedDepartment));
    }
}

@using CourseCatalog.Models

<div class="row row-cols-1 row-cols-md-2 row-cols-lg-3 g-4">
    @foreach (var course in Courses)
    {
        <div class="col">
            <CourseCard Course="course" />
        </div>
    }
</div>

@if (!Courses.Any())
{
    <div class="alert alert-info mt-3">No courses match your search criteria.</div>
}

