    {
        <DepartmentLinks Departments="_departments" />
    }
</section>

<section>
    <h2 class="mb-3">Featured Courses</h2>
    @if (_featured is not null)
    {
        <CourseList Courses="_featured" />
    }
</section>

@code {
    private IReadOnlyList<Department>? _departments;
    private IReadOnlyList<Course>? _featured;

    protected override async Task OnInitializedAsync()
    {
        _departments = await Catalog.GetDepartmentsAsync();
        _featured = await Catalog.GetFeaturedCoursesAsync();
    }
}

