@page "/catalog"
@using CourseCatalog.Models
@using CourseCatalog.Services
@inject ICatalogService Catalog
@inject NavigationManager Nav

<PageTitle>Course Catalog</PageTitle>

<h1 class="mb-4">Course Catalog</h1>

<CourseFilters Departments="_departments" FiltersChanged="HandleFiltersChanged" />

<CourseList Courses="_courses" />

@code {
    [SupplyParameterFromQuery(Name = "dept")]
    public string? DepartmentFilter { get; set; }

    private IReadOnlyList<Department> _departments = [];
    private IReadOnlyList<Course> _courses = [];
    private string? _searchTerm;

    protected override async Task OnInitializedAsync()
    {
        _departments = await Catalog.GetDepartmentsAsync();
        _courses = await Catalog.GetCoursesAsync(departmentCode: DepartmentFilter);
    }

    private async Task HandleFiltersChanged((string? Search, string? Department) filters)
    {
        _searchTerm = filters.Search;
        _courses = await Catalog.GetCoursesAsync(filters.Search, filters.Department);
    }
}

@page "/course/{Id:int}"
@using CourseCatalog.Models
@using CourseCatalog.Services
@inject ICatalogService Catalog

<PageTitle>@(_course?.Title ?? "Course Detail")</PageTitle>

@if (_course is null)
{
    <div class="alert alert-warning">Course not found.</div>
}
else
{
    <nav aria-label="breadcrumb" class="mb-3">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="catalog">Catalog</a></li>
            <li class="breadcrumb-item active" aria-current="page">@_course.Code</li>
        </ol>
    </nav>

    <h1>@_course.Title</h1>
    <span class="badge bg-secondary me-2">@_course.Code</span>
    <span class="badge bg-info">@_course.Credits Credits</span>

    <p class="mt-3">@_course.Description</p>

    <div class="card mt-4">
        <div class="card-body">
            <h5 class="card-title">Schedule</h5>
            <p class="card-text">@_course.Schedule</p>
        </div>
    </div>

    <InstructorBio Name="@_course.InstructorName" Bio="@_course.InstructorBio" />

    <div class="mt-4">
        <a href="@($"enroll?courseId={_course.Id}")" class="btn btn-primary">Request Enrollment</a>
        <a href="catalog" class="btn btn-outline-secondary ms-2">Back to Catalog</a>
    </div>
}

@code {
    [Parameter] public int Id { get; set; }

    private Course? _course;

    protected override async Task OnInitializedAsync()
    {
        _course = await Catalog.GetCourseByIdAsync(Id);
    }
}

@page "/enroll"
@using CourseCatalog.Models
@using CourseCatalog.Services
@inject ICatalogService Catalog

<PageTitle>Enrollment Request</PageTitle>

<h1 class="mb-4">Enrollment Request</h1>

@if (_submitted)
{
    <div class="alert alert-success">
        <h4 class="alert-heading">Request Submitted!</h4>
        <p>Your enrollment request for <strong>@_selectedCourseTitle</strong> has been received. You will be notified by email once it is processed.</p>
        <a href="catalog" class="btn btn-outline-success mt-2">Browse More Courses</a>
    </div>
}
else
{
    <EditForm Model="_model" OnValidSubmit="HandleSubmit" FormName="enrollment">
        <DataAnnotationsValidator />
        <ValidationSummary class="text-danger mb-3" />

        <div class="mb-3">
            <label for="fullName" class="form-label">Full Name</label>
            <InputText id="fullName" class="form-control" @bind-Value="_model.FullName" />
            <ValidationMessage For="() => _model.FullName" />
        </div>

        <div class="mb-3">
            <label for="studentId" class="form-label">Student ID</label>
            <InputText id="studentId" class="form-control" placeholder="e.g., CS123456" @bind-Value="_model.StudentId" />
            <ValidationMessage For="() => _model.StudentId" />
        </div>

        <div class="mb-3">
            <label for="courseSelect" class="form-label">Course</label>
            <InputSelect id="courseSelect" class="form-select" @bind-Value="_model.CourseId">
                <option value="0">— Select a course —</option>
                @foreach (var course in _courses)
                {
                    <option value="@course.Id">@course.Code — @course.Title</option>
                }
            </InputSelect>
            <ValidationMessage For="() => _model.CourseId" />
        </div>

        <button type="submit" class="btn btn-primary">Submit Request</button>
        <a href="catalog" class="btn btn-outline-secondary ms-2">Cancel</a>
    </EditForm>
}

@code {
    [SupplyParameterFromQuery(Name = "courseId")]
    public int? PreselectedCourseId { get; set; }

    private EnrollmentRequest _model = new();
    private IReadOnlyList<Course> _courses = [];
    private bool _submitted;
    private string _selectedCourseTitle = "";

    protected override async Task OnInitializedAsync()
    {
        _courses = await Catalog.GetCoursesAsync();
        if (PreselectedCourseId.HasValue)
            _model.CourseId = PreselectedCourseId.Value;
    }

    private async Task HandleSubmit()
    {
        var course = _courses.FirstOrDefault(c => c.Id == _model.CourseId);
        _selectedCourseTitle = course is not null ? $"{course.Code} — {course.Title}" : "Unknown";
        await Catalog.SubmitEnrollmentAsync(_model);
        _submitted = true;
    }
}

