@page "/course/{Id:int}"
@using CourseCatalog.Models
@using CourseCatalog.Services
@inject ICatalogService Catalog

<PageTitle>@(_course?.Title ?? "Course Detail")</PageTitle>

@if (_course is null)
{
    <div class="alert alert-warning">Course not found.</div>
}
else
{
    <nav aria-label="breadcrumb" class="mb-3">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="catalog">Catalog</a></li>
            <li class="breadcrumb-item active" aria-current="page">@_course.Code</li>
        </ol>
    </nav>

    <h1>@_course.Title</h1>
    <span class="badge bg-secondary me-2">@_course.Code</span>
    <span class="badge bg-info">@_course.Credits Credits</span>

    <p class="mt-3">@_course.Description</p>

    <div class="card mt-4">
        <div class="card-body">
            <h5 class="card-title">Schedule</h5>
            <p class="card-text">@_course.Schedule</p>
        </div>
    </div>

    <InstructorBio Name="@_course.InstructorName" Bio="@_course.InstructorBio" />

    <div class="mt-4">
        <a href="@($"enroll?courseId={_course.Id}")" class="btn btn-primary">Request Enrollment</a>
        <a href="catalog" class="btn btn-outline-secondary ms-2">Back to Catalog</a>
    </div>
}

@code {
    [Parameter] public int Id { get; set; }

    private Course? _course;

    protected override async Task OnInitializedAsync()
    {
        _course = await Catalog.GetCourseByIdAsync(Id);
    }
}

